import {
  Group,
  Mesh,
  PlaneGeometry,
  Shape,
  ExtrudeGeometry,
  OctahedronGeometry,
  MeshPhysicalNodeMaterial,
  MeshStandardNodeMaterial,
  DirectionalLight,
  Color,
  DoubleSide,
  MathUtils
} from 'three/webgpu';
import {
  uv,
  mix,
  color,
  smoothstep
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {any} textContent
 * @property {any} intent
 * @property {Array<{name:string,params:any,trigger:string}>} cinematicPrimitives
 * @property {string} [imageUrl]
 * @property {string} [depthMapUrl]
 * @property {string} [meshUrl]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {{loadTexture(url:string):Promise<any>}} textureLoader
 * @property {{loadGLB(url:string):Promise<any>}} glbLoader
 * @property {{loadVideo?(url:string):Promise<any>}} videoLoader
 * @property {{createText(content:string, opts?:any):import('three').Object3D}} fontAtlas
 * @property {{[key:string]:(target:any, params:any)=>{timeline:any, cleanup:()=>void}}} primitives
 * @property {(event:string, payload:any)=>void} emit
 * @property {string} [tier]
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  // ----------------------
  // Helpers & cleanup list
  // ----------------------
  const disposables = [];

  function disposeAll() {
    disposables.forEach((d) => {
      try {
        if (d.isTexture) d.dispose();
        else if (d.isMaterial) d.dispose();
        else if (d.isGeometry) d.dispose();
      } catch (e) {}
    });
    disposables.length = 0;
  }

  const primitiveHandles = [];

  // ----------
  // Main group
  // ----------
  const root = new Group();

  // ---------------------------------
  // Backdrop plane with vertical gradient
  // ---------------------------------
  const backdropGeom = new PlaneGeometry(7, 6);
  disposables.push(backdropGeom);

  const gradStops = config.visual?.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.6, hex: '#12121a' },
    { at: 1, hex: '#16161d' }
  ];

  const backdropMaterial = new MeshStandardNodeMaterial({
    transparent: false,
    side: DoubleSide,
    depthWrite: true,
    roughness: 1,
    metalness: 0,
    color: mix(
      mix(
        color(new Color(gradStops[0].hex)),
        color(new Color(gradStops[1].hex)),
        smoothstep(gradStops[0].at, gradStops[1].at, uv().y)
      ),
      color(new Color(gradStops[2].hex)),
      smoothstep(gradStops[1].at, gradStops[2].at, uv().y)
    )
  });
  disposables.push(backdropMaterial);

  const backdropMesh = new Mesh(backdropGeom, backdropMaterial);
  backdropMesh.position.set(0, 0, -2.5);
  root.add(backdropMesh);

  // -----------------------
  // Prism geometry & material
  // -----------------------
  const prismSide = 1.2;
  const prismLength = 1.8;

  // Build equilateral triangle shape centered at origin
  const r = prismSide / Math.sqrt(3);
  const triangleShape = new Shape();
  triangleShape.moveTo(0, r);
  triangleShape.lineTo(-prismSide / 2, -r / 2);
  triangleShape.lineTo(prismSide / 2, -r / 2);
  triangleShape.lineTo(0, r); // close

  const prismGeom = new ExtrudeGeometry(triangleShape, {
    depth: prismLength,
    bevelEnabled: false
  });
  prismGeom.center();
  disposables.push(prismGeom);

  const prismMaterial = new MeshPhysicalNodeMaterial({
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    roughness: 0.08,
    metalness: 0,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    attenuationColor: new Color('#e8ecf2'),
    attenuationDistance: 2.5,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    iridescenceThicknessRange: [120, 480],
    // approximate dispersion (if supported)
    // @ts-ignore - property may exist in node material
    dispersion: 0.18,
    color: new Color('#ffffff')
  });
  disposables.push(prismMaterial);

  const prismMesh = new Mesh(prismGeom, prismMaterial);
  prismMesh.rotation.z = MathUtils.degToRad(12);
  prismMesh.rotation.y = MathUtils.degToRad(20);
  root.add(prismMesh);

  // ---------------------------------
  // Emissive core (octahedron inside prism)
  // ---------------------------------
  const coreGeom = new OctahedronGeometry(0.35);
  disposables.push(coreGeom);

  const coreMaterial = new MeshStandardNodeMaterial({
    color: new Color('#000000'),
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 2.2,
    roughness: 1,
    metalness: 0
  });
  disposables.push(coreMaterial);

  const coreMesh = new Mesh(coreGeom, coreMaterial);
  root.add(coreMesh);

  // -----------------------
  // Rim back light
  // -----------------------
  const rimLight = new DirectionalLight(new Color('#e8ecf2'), 0.8);
  rimLight.position.set(-2, 0, 2);
  rimLight.target.position.set(0, 0, 0);
  root.add(rimLight);
  root.add(rimLight.target);

  // -----------------------
  // Caustic streak on floor
  // -----------------------
  const causticGeom = new PlaneGeometry(2.4, 0.5);
  disposables.push(causticGeom);

  const causticMaterial = new MeshStandardNodeMaterial({
    transparent: true,
    opacity: 0.35,
    side: DoubleSide,
    depthWrite: false,
    color: mix(
      mix(
        color(new Color('#ff2a38')),
        color(new Color('#e8ecf2')),
        smoothstep(0.2, 0.5, uv().x)
      ),
      color(new Color('#9fb0c4')),
      smoothstep(0.5, 0.8, uv().x)
    )
  });
  disposables.push(causticMaterial);

  const causticMesh = new Mesh(causticGeom, causticMaterial);
  causticMesh.rotation.x = -Math.PI / 2;
  causticMesh.position.set(0, -1.1, 0);
  root.add(causticMesh);

  // -----------------------
  // Text content via font atlas
  // -----------------------
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  let headlineObj = null;
  let captionObj = null;

  for (const item of textItems) {
    const isHeadline = item.role === 'headline' || (item.typography?.fontWeight === 600);
    const opts = {
      fontSize: isHeadline ? 68 : 18,
      color: isHeadline ? '#16161d' : '#e8ecf2',
      align: 'center',
      maxWidthPx: 1024
    };
    const txt = ctx.fontAtlas.createText(item.text, opts);
    if (isHeadline) {
      headlineObj = txt;
      txt.position.set(0, -1.75, 0);
    } else {
      captionObj = txt;
      txt.position.set(0, -2.25, 0);
    }
    root.add(txt);
  }

  // -----------------------
  // Apply cinematic primitives from config
  // -----------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (typeof ctx.primitives[prim.name] === 'function') {
        const handle = ctx.primitives[prim.name](root, prim.params);
        primitiveHandles.push(handle);
      }
    }
  }

  // -----------------------
  // UserData hooks & cleanup
  // -----------------------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // cleanup primitives
    primitiveHandles.forEach((h) => {
      try {
        if (h && typeof h.cleanup === 'function') h.cleanup();
        if (h && h.timeline) gsap.killTweensOf(h.timeline);
      } catch (e) {}
    });
    primitiveHandles.length = 0;

    // dispose three objects
    disposeAll();

    // kill any stray gsap animations (safety)
    gsap.globalTimeline.clear();
  };

  return root;
}
